using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Collect all errors and warnings
var errors = new List<(string project, string code, string message, string file, int line)>();
var warnings = new List<(string project, string code, string message, string file, int line)>();
var failedProjects = new HashSet<string>();

build.VisitAllChildren<Error>(e => {
    var proj = "";
    var node = e.Parent;
    while (node != null) {
        if (node is Project p) { proj = p.Name; break; }
        node = node.Parent;
    }
    errors.Add((proj, e.Code ?? "", e.Text ?? e.ToString(), e.File ?? "", e.LineNumber));
});

build.VisitAllChildren<Project>(p => {
    if (!p.Succeeded) failedProjects.Add(p.Name);
});

Console.WriteLine("=== FAILED PROJECTS ===");
foreach (var p in failedProjects.OrderBy(x => x))
    Console.WriteLine($"  - {p}");

Console.WriteLine($"\n=== ERRORS ({errors.Count}) ===");
foreach (var g in errors.GroupBy(e => e.project).OrderBy(g => g.Key))
{
    Console.WriteLine($"\n  Project: {g.Key}");
    foreach (var e in g)
        Console.WriteLine($"    [{e.code}] {e.file}({e.line}): {e.message}");
}

// Also check for dependency failures
Console.WriteLine("\n=== DEPENDENCY ANALYSIS ===");
build.VisitAllChildren<Project>(p => {
    if (!p.Succeeded) {
        // Check if it has MSB3202 or similar dependency errors
        var hasDependencyError = false;
        var hasOwnError = false;
        p.VisitAllChildren<Error>(e => {
            if (e.Code == "MSB3202" || e.Code == "MSB4181" || 
                (e.Text ?? "").Contains("could not be resolved") ||
                (e.Text ?? "").Contains("dependency"))
                hasDependencyError = true;
            else
                hasOwnError = true;
        });

        var errorCount = 0;
        p.VisitAllChildren<Error>(e => errorCount++);

        if (errorCount == 0)
            Console.WriteLine($"  {p.Name}: FAILED with no direct errors (cascading from dependency)");
        else if (hasDependencyError && !hasOwnError)
            Console.WriteLine($"  {p.Name}: FAILED due to dependency errors only (cascading)");
        else
            Console.WriteLine($"  {p.Name}: FAILED with own errors (ROOT CAUSE)");
    }
});
