using System;
using System.Collections.Generic;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;
using P = Microsoft.Build.Logging.StructuredLogger.Project;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

var errors = new List<(string project, string code, string message, string file, int line)>();

build.VisitAllChildren<Error>(e => {
    var proj = "";
    var node = (BaseNode)e;
    while (node != null) {
        if (node is P p) { proj = p.Name; break; }
        node = node.Parent as BaseNode;
    }
    errors.Add((proj, e.Code ?? "", e.Text ?? e.ToString(), e.File ?? "", e.LineNumber));
});

// Get project dependency info
var projectDeps = new Dictionary<string, List<string>>();
build.VisitAllChildren<P>(p => {
    var deps = new List<string>();
    p.VisitAllChildren<Microsoft.Build.Logging.StructuredLogger.ProjectReference>(pr => {
        deps.Add(pr.Name ?? pr.ToString());
    });
    if (!projectDeps.ContainsKey(p.Name))
        projectDeps[p.Name] = deps;
});

Console.WriteLine($"=== ALL ERRORS ({errors.Count}) ===");
foreach (var g in errors.GroupBy(e => e.project).OrderBy(g => g.Key))
{
    Console.WriteLine($"\n  Project: {g.Key}");
    foreach (var e in g.OrderBy(x => x.file).ThenBy(x => x.line))
        Console.WriteLine($"    [{e.code}] {e.file}({e.line}): {e.message}");
}

// Identify which projects have errors vs just dependency failures
var projectsWithErrors = errors.GroupBy(e => e.project).Select(g => g.Key).ToHashSet();
var projectsWithOnlyDepErrors = new HashSet<string>();
foreach (var proj in projectsWithErrors)
{
    var projErrors = errors.Where(e => e.project == proj).ToList();
    // If all errors reference missing types/assemblies that come from other failed projects
    var allAreDep = projErrors.All(e => 
        e.code == "MSB3202" || e.code == "MSB3270" || e.code == "MSB3277" ||
        e.code == "MSB4236" || 
        e.message.Contains("could not be resolved") ||
        e.message.Contains("does not exist in the project") ||
        (e.code == "CS0006" && e.message.Contains("metadata file")));
    if (allAreDep) projectsWithOnlyDepErrors.Add(proj);
}

Console.WriteLine("\n=== ROOT CAUSE vs CASCADING ===");
foreach (var proj in projectsWithErrors.OrderBy(x => x))
{
    if (projectsWithOnlyDepErrors.Contains(proj))
        Console.WriteLine($"  CASCADING: {proj}");
    else
        Console.WriteLine($"  ROOT CAUSE: {proj}");
}
